/**
 * The app's icon set: Solar (Linear style) by 480 Design (CC BY 4.0), drawn at a 1.7 px stroke like
 * Zeron. Only the icons in use ship, as static data generated by scripts/build-solar-icons.mjs into
 * ./solar-data.ts. Lucide-era export names stay stable so call sites do not change; `fill` other than
 * "none" (or `weight="fill"`) selects the Solar Bold glyph for active and pinned items. ADR-177.
 */
import { forwardRef, memo, type ComponentType, type SVGProps } from "react";
import { SOLAR_ICONS, SOLAR_ICON_NAMES } from "./solar-data";

export interface IconProps extends Omit<SVGProps<SVGSVGElement>, "ref" | "fill"> {
  /** Pixels; Zeron's row icons are 16. */
  size?: number | string;
  /** Ignored: Solar Linear is drawn at 1.7 everywhere (kept for call-site compatibility). */
  strokeWidth?: number | string;
  absoluteStrokeWidth?: boolean;
  /** Any value other than "none" renders the Bold glyph. */
  fill?: string;
  /** "fill" renders the Bold glyph; "bold" thickens the linear stroke; anything else is the regular look. */
  weight?: "thin" | "light" | "regular" | "bold" | "fill" | "duotone";
  color?: string;
}
export type LucideIcon = ComponentType<IconProps>;

/** Linear stroke for `weight="bold"`. */
const HEAVY_STROKE = "2.2";
/** Icons that add a stroke on top of another glyph's drawing. */
const OVERLAY: Partial<Record<string, string>> = {
  PinOff: '<path stroke="currentColor" stroke-width="1.7" stroke-linecap="round" d="M4 4l16 16"/>',
};

function make(name: keyof typeof SOLAR_ICON_NAMES): LucideIcon {
  const [linear, bold] = SOLAR_ICONS[SOLAR_ICON_NAMES[name]];
  const overlay = OVERLAY[name] ?? "";
  const regular = linear + overlay;
  const heavy = linear.replaceAll('stroke-width="1.7"', `stroke-width="${HEAVY_STROKE}"`) + overlay;
  const filled = (bold ?? linear) + overlay;
  const Icon = forwardRef<SVGSVGElement, IconProps>(function Icon(
    { size = 16, strokeWidth, absoluteStrokeWidth, fill, weight, ...rest },
    ref,
  ) {
    void strokeWidth;
    void absoluteStrokeWidth;
    const solid = weight === "fill" || (weight === undefined && !!fill && fill !== "none");
    const html = solid ? filled : weight === "bold" ? heavy : regular;
    return <svg ref={ref} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width={size} height={size} {...rest} dangerouslySetInnerHTML={{ __html: html }} />;
  });
  Icon.displayName = name;
  return memo(Icon) as unknown as LucideIcon;
}

